// =====================================================================
// CONFIGURAÇÃO DA AGENDA DA LORENA
// Valores marcados com "EXEMPLO" ainda precisam ser confirmados com ela.
// =====================================================================
const CONFIG = {
  fuso: 'America/Sao_Paulo',

  // ID da agenda do Google. "primary" = agenda principal da conta conectada.
  // Para usar uma agenda separada ("Atendimentos"), cole o ID dela aqui
  // (Configurações da agenda > Integrar agenda > ID da agenda).
  agendaId: 'primary',

  // Expediente por dia da semana: 1 = segunda ... 6 = sábado, 7 = domingo.
  // Dia sem entrada = fechado. Pausas (almoço) = duas faixas no mesmo dia.
  // EXEMPLO: confirmar com a Lorena.
  expediente: {
    1: [['09:00', '12:00'], ['13:00', '18:00']],
    2: [['09:00', '12:00'], ['13:00', '18:00']],
    3: [['09:00', '12:00'], ['13:00', '18:00']],
    4: [['09:00', '12:00'], ['13:00', '18:00']],
    5: [['09:00', '12:00'], ['13:00', '18:00']],
    6: [['09:00', '13:00']],
  },

  // Duração de cada atendimento em minutos. EXEMPLO: confirmar com a Lorena.
  duracoes: {
    avaliacao: 60,
    retorno: 30,
    bioestimuladores: 60,
    skinbooster: 60,
    harmonizacao_facial: 90,
    limpeza_de_pele: 90,
    peeling: 60,
    microagulhamento: 90,
  },
  duracaoPadrao: 60,

  // Nome que aparece no evento e nas mensagens.
  nomes: {
    avaliacao: 'Avaliação',
    retorno: 'Retorno',
    bioestimuladores: 'Bioestimuladores',
    skinbooster: 'Skinbooster',
    harmonizacao_facial: 'Harmonização facial',
    limpeza_de_pele: 'Limpeza de pele',
    peeling: 'Peeling',
    microagulhamento: 'Microagulhamento',
  },

  intervaloEntreAtendimentosMin: 15, // folga para limpar a sala e preparar a próxima
  passoMinutos: 30,                  // de quanto em quanto tempo oferecer horários
  antecedenciaMinimaHoras: 2,        // não agenda para daqui a menos de 2 h
  diasMaximosNoFuturo: 60,           // agenda aberta até 60 dias à frente
  maxHorariosPorDia: 4,              // quantos horários sugerir por dia
  maxHorariosPorConsulta: 12,        // total por consulta (o agente oferece 2 a 4)
  cancelamentoAutomaticoAteHoras: 12, // com menos que isso, quem decide é a Lorena (EXEMPLO)
};

// ---------------------------------------------------------------------
const e = $input.first().json;
const txt = (v) => (v === null || v === undefined ? '' : String(v).trim());
const semAcento = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

function chaveProcedimento(p) {
  const s = semAcento(txt(p));
  if (!s) return 'avaliacao';
  if (s.includes('avalia')) return 'avaliacao';
  if (s.includes('retorno')) return 'retorno';
  if (s.includes('bioestim')) return 'bioestimuladores';
  if (s.includes('skin')) return 'skinbooster';
  if (s.includes('harmoniz')) return 'harmonizacao_facial';
  if (s.includes('limpeza')) return 'limpeza_de_pele';
  if (s.includes('peeling')) return 'peeling';
  if (s.includes('microagulh')) return 'microagulhamento';
  return 'avaliacao';
}

const chave = chaveProcedimento(e.procedimento);

return [{
  json: {
    acao: semAcento(txt(e.acao)),
    telefone: txt(e.telefone).replace(/\D/g, ''),
    nome: txt(e.nome),
    procedimento: chave,
    procedimento_nome: CONFIG.nomes[chave] || chave,
    duracao: CONFIG.duracoes[chave] || CONFIG.duracaoPadrao,
    data_inicio: txt(e.data_inicio),
    data_fim: txt(e.data_fim),
    inicio: txt(e.inicio),
    evento_id: txt(e.evento_id),
    motivo: txt(e.motivo),
    phone_number_id: txt(e.phone_number_id),
    lorena_whatsapp: txt(e.lorena_whatsapp).replace(/\D/g, ''),
    cfg: CONFIG,
  },
}];

// Define a janela de datas da consulta (no máximo 14 dias, nunca no passado)
// e monta o pedido de "livre/ocupado" (freeBusy) para o Google Agenda.
const d = $input.first().json;
const cfg = d.cfg;
const z = cfg.fuso;
const agora = DateTime.now().setZone(z);
const hoje = agora.startOf('day');
const limite = hoje.plus({ days: cfg.diasMaximosNoFuturo });

const lerData = (s) => {
  const v = DateTime.fromISO(String(s || '').slice(0, 10), { zone: z });
  return v.isValid ? v.startOf('day') : null;
};

let ini = lerData(d.data_inicio) || hoje;
if (ini < hoje) ini = hoje;
const foraDoLimite = ini > limite;
if (foraDoLimite) ini = limite;

let fim = lerData(d.data_fim) || ini.plus({ days: 6 });
if (fim < ini) fim = ini;
if (fim > limite) fim = limite;
if (fim.diff(ini, 'days').days > 13) fim = ini.plus({ days: 13 });

const janelaFim = fim.endOf('day');

return [{
  json: {
    janela_inicio: ini.toISO(),
    janela_fim: janelaFim.toISO(),
    fora_do_limite: foraDoLimite,
    freebusy: {
      timeMin: ini.toISO(),
      timeMax: janelaFim.toISO(),
      timeZone: z,
      items: [{ id: cfg.agendaId }],
    },
  },
}];

// Cruza o expediente com os horários ocupados do Google Agenda
// e devolve opções livres, espalhadas ao longo de cada dia.
const d = $('Config').first().json;
const cfg = d.cfg;
const p = $('Montar consulta').first().json;
const resp = $input.first().json;
const z = cfg.fuso;

const cal = Object.values(resp.calendars || {})[0] || {};
if (cal.errors && cal.errors.length) {
  return [{ json: { resultado: 'Não consegui ler a agenda agora. Peça desculpas e use chamar_lorena para ela confirmar o horário pessoalmente.' } }];
}

const ocupados = (cal.busy || []).map((b) => ({
  s: DateTime.fromISO(b.start).toMillis(),
  e: DateTime.fromISO(b.end).toMillis(),
}));
const folga = cfg.intervaloEntreAtendimentosMin * 60000;
const livre = (s, e) => ocupados.every((b) => e + folga <= b.s || b.e + folga <= s);
const hm = (t) => { const [h, m] = t.split(':').map(Number); return { hour: h, minute: m, second: 0, millisecond: 0 }; };

const agora = DateTime.now().setZone(z);
const minimo = agora.plus({ hours: cfg.antecedenciaMinimaHoras });
const dur = d.duracao;

// Escolhe k itens espalhados (manhã e tarde) em vez dos k primeiros.
function espalhar(lista, k) {
  if (lista.length <= k) return lista;
  const out = [];
  for (let i = 0; i < k; i++) out.push(lista[Math.round((i * (lista.length - 1)) / (k - 1))]);
  return out;
}

const dias = [];
let total = 0;
let dia = DateTime.fromISO(p.janela_inicio, { zone: z }).startOf('day');
const ultimo = DateTime.fromISO(p.janela_fim, { zone: z }).startOf('day');

while (dia <= ultimo && total < cfg.maxHorariosPorConsulta) {
  const faixas = cfg.expediente[dia.weekday] || [];
  const opcoes = [];
  for (const [a, b] of faixas) {
    let s = dia.set(hm(a));
    const fimFaixa = dia.set(hm(b));
    while (s.plus({ minutes: dur }) <= fimFaixa) {
      const e = s.plus({ minutes: dur });
      if (s >= minimo && livre(s.toMillis(), e.toMillis())) opcoes.push(s);
      s = s.plus({ minutes: cfg.passoMinutos });
    }
  }
  if (opcoes.length) {
    const k = Math.min(cfg.maxHorariosPorDia, cfg.maxHorariosPorConsulta - total);
    const escolhidos = espalhar(opcoes, k);
    dias.push({ dia, horarios: escolhidos });
    total += escolhidos.length;
  }
  dia = dia.plus({ days: 1 });
}

const fmtDia = (x) => x.setLocale('pt-BR').toFormat("cccc, dd/MM/yyyy");
const ini = DateTime.fromISO(p.janela_inicio, { zone: z });
const fim = DateTime.fromISO(p.janela_fim, { zone: z });

if (!dias.length) {
  const extra = p.fora_do_limite ? ` A agenda só está aberta até ${cfg.diasMaximosNoFuturo} dias à frente.` : '';
  return [{ json: { resultado: `Nenhum horário livre para ${d.procedimento_nome} (${dur} min) entre ${fmtDia(ini)} e ${fmtDia(fim)}.${extra} Ofereça consultar outro período.` } }];
}

const linhas = dias.map(({ dia: x, horarios }) =>
  `- ${fmtDia(x)}: ` + horarios.map((h) => `${h.toFormat('HH:mm')} [${h.toFormat("yyyy-MM-dd'T'HH:mm")}]`).join(', ')
);

return [{
  json: {
    resultado:
      `Horários livres para ${d.procedimento_nome} (${dur} min):\n` + linhas.join('\n') +
      '\nO valor entre colchetes é o código para a ferramenta agendar. Não mostre o código para a paciente; ofereça de 2 a 4 opções em linguagem natural.',
  },
}];

// Confere o pedido de agendamento antes de tocar na agenda:
// nome, formato da data, antecedência, limite de dias e expediente.
const d = $input.first().json;
const cfg = d.cfg;
const z = cfg.fuso;
const erro = (m) => [{ json: { ok: false, resultado: m } }];

if (!d.telefone) return erro('Telefone da paciente ausente. Use chamar_lorena.');
if (d.nome.length < 3) return erro('Falta o nome completo da paciente. Pergunte antes de agendar.');

let ini = DateTime.fromISO(d.inicio, { zone: z });
if (!d.inicio || !ini.isValid) {
  return erro('Data e hora inválidas. Use o código AAAA-MM-DDTHH:MM exatamente como veio de consultar_horarios.');
}
ini = ini.set({ second: 0, millisecond: 0 });
const fim = ini.plus({ minutes: d.duracao });
const agora = DateTime.now().setZone(z);

if (ini < agora.plus({ hours: cfg.antecedenciaMinimaHoras })) {
  return erro(`Esse horário já passou ou está muito próximo (antecedência mínima de ${cfg.antecedenciaMinimaHoras} h). Consulte outros horários.`);
}
if (ini >= agora.startOf('day').plus({ days: cfg.diasMaximosNoFuturo + 1 })) {
  return erro(`A agenda só está aberta até ${cfg.diasMaximosNoFuturo} dias à frente. Ofereça uma data mais próxima.`);
}

const hm = (t) => { const [h, m] = t.split(':').map(Number); return { hour: h, minute: m, second: 0, millisecond: 0 }; };
const faixas = cfg.expediente[ini.weekday] || [];
const cabe = faixas.some(([a, b]) => ini >= ini.set(hm(a)) && fim <= ini.set(hm(b)));
if (!cabe) return erro('Esse horário está fora do expediente. Use consultar_horarios e ofereça um dos horários livres.');

const folga = cfg.intervaloEntreAtendimentosMin;
const quando = ini.setLocale('pt-BR').toFormat("cccc, dd/MM/yyyy 'às' HH:mm");

const evento = {
  summary: `${d.procedimento_nome} · ${d.nome}`,
  description:
    'Agendado pelo assistente do WhatsApp.\n' +
    `Paciente: ${d.nome}\n` +
    `WhatsApp: https://wa.me/${d.telefone}\n` +
    `Procedimento: ${d.procedimento_nome} (${d.duracao} min)`,
  start: { dateTime: ini.toISO(), timeZone: z },
  end: { dateTime: fim.toISO(), timeZone: z },
  extendedProperties: { private: { telefone: d.telefone, origem: 'assistente-whatsapp', procedimento: d.procedimento } },
  reminders: { useDefault: true },
};

return [{
  json: {
    ok: true,
    inicio: ini.toISO(),
    fim: fim.toISO(),
    quando,
    evento,
    freebusy: {
      timeMin: ini.minus({ minutes: folga }).toISO(),
      timeMax: fim.plus({ minutes: folga }).toISO(),
      timeZone: z,
      items: [{ id: cfg.agendaId }],
    },
    aviso_lorena:
      `Novo agendamento pelo assistente\n${d.procedimento_nome} · ${quando}\n` +
      `Paciente: ${d.nome}\nWhatsApp: https://wa.me/${d.telefone}`,
  },
}];

// Segunda checagem, logo antes de criar o evento: o horário ainda está livre?
// (Evita marcar duas pacientes no mesmo horário.)
const cfg = $('Config').first().json.cfg;
const p = $('Validar pedido').first().json;
const resp = $input.first().json;

const cal = Object.values(resp.calendars || {})[0] || {};
if (cal.errors && cal.errors.length) {
  return [{ json: { livre: false, resultado: 'Não consegui confirmar a agenda agora. Peça desculpas e use chamar_lorena.' } }];
}

const s = DateTime.fromISO(p.inicio).toMillis();
const e = DateTime.fromISO(p.fim).toMillis();
const folga = cfg.intervaloEntreAtendimentosMin * 60000;
const conflito = (cal.busy || []).some((b) => {
  const bs = DateTime.fromISO(b.start).toMillis();
  const be = DateTime.fromISO(b.end).toMillis();
  return !(e + folga <= bs || be + folga <= s);
});

return [{
  json: {
    livre: !conflito,
    resultado: conflito ? 'Esse horário acabou de ser ocupado. Use consultar_horarios de novo e ofereça outras opções.' : '',
  },
}];

// Resposta final do agendamento para o agente.
const p = $('Validar pedido').first().json;
const d = $('Config').first().json;
const ev = $('Criar evento').first().json;

return [{
  json: {
    resultado:
      `Agendado: ${d.procedimento_nome} em ${p.quando} (evento_id: ${ev.id}). ` +
      'Confirme para a paciente o dia, o horário e o endereço, e diga que, se precisar desmarcar, é só avisar por aqui.',
  },
}];

// Lista os próximos agendamentos deste número (só os criados pelo assistente,
// que guardam o telefone no evento).
const cfg = $('Config').first().json.cfg;
const z = cfg.fuso;
const itens = ($input.first().json.items || []).filter((ev) => ev.status !== 'cancelled');

if (!itens.length) {
  return [{
    json: {
      resultado:
        'Nenhum agendamento futuro encontrado para este número de WhatsApp. ' +
        'Se a paciente diz que tem horário (pode ter sido marcado direto com a Lorena ou por outro número), use chamar_lorena.',
    },
  }];
}

const nomeProc = (ev) => {
  const k = ev.extendedProperties?.private?.procedimento;
  return cfg.nomes[k] || String(ev.summary || 'Atendimento').split(' · ')[0];
};

const linhas = itens.map((ev) => {
  const ini = DateTime.fromISO(ev.start?.dateTime || ev.start?.date, { zone: z });
  return `- ${nomeProc(ev)}: ${ini.setLocale('pt-BR').toFormat("cccc, dd/MM/yyyy 'às' HH:mm")} (evento_id: ${ev.id})`;
});

return [{
  json: {
    resultado: `Próximos agendamentos deste número:\n${linhas.join('\n')}\nNão mostre o evento_id para a paciente.`,
  },
}];

// Antes de cancelar: o evento existe, é deste número, é futuro
// e respeita a antecedência mínima para cancelar pelo assistente.
const d = $('Config').first().json;
const cfg = d.cfg;
const z = cfg.fuso;
const r = $input.first().json;
const ev = r.body && typeof r.body === 'object' ? r.body : {};
const erro = (m) => [{ json: { ok: false, resultado: m } }];
const digitos = (v) => String(v || '').replace(/\D/g, '');

if (!d.evento_id) return erro('Falta o evento_id. Use listar_meus_agendamentos primeiro.');
if (r.statusCode !== 200 || !ev.id || ev.status === 'cancelled') {
  return erro('Agendamento não encontrado ou já cancelado. Use listar_meus_agendamentos para ver os atuais.');
}
if (digitos(ev.extendedProperties?.private?.telefone) !== digitos(d.telefone)) {
  return erro('Esse agendamento não pertence a este número. Não cancele. Use listar_meus_agendamentos.');
}

const ini = DateTime.fromISO(ev.start?.dateTime || ev.start?.date, { zone: z });
const agora = DateTime.now().setZone(z);
if (ini <= agora) return erro('Esse agendamento já passou e não pode ser cancelado.');

const quando = ini.setLocale('pt-BR').toFormat("cccc, dd/MM/yyyy 'às' HH:mm");
const proc = cfg.nomes[ev.extendedProperties?.private?.procedimento] || String(ev.summary || 'Atendimento').split(' · ')[0];

if (ini.diff(agora, 'hours').hours < cfg.cancelamentoAutomaticoAteHoras) {
  return erro(
    `Faltam menos de ${cfg.cancelamentoAutomaticoAteHoras} horas para ${proc} (${quando}). ` +
    'Não cancele pelo assistente: use chamar_lorena com o motivo "cancelamento em cima da hora" e avise a paciente que a Lorena vai responder.'
  );
}

const paciente = String(ev.summary || '').split(' · ')[1] || 'paciente';
return [{
  json: {
    ok: true,
    evento_id: ev.id,
    quando,
    procedimento_nome: proc,
    aviso_lorena: `Cancelamento pelo assistente\n${proc} · ${quando}\nPaciente: ${paciente}\nWhatsApp: https://wa.me/${d.telefone}\nO horário ficou livre na agenda.`,
  },
}];

// Resposta final do cancelamento para o agente.
const p = $('Conferir dono').first().json;
return [{
  json: {
    resultado: `Cancelado: ${p.procedimento_nome} de ${p.quando}. Confirme o cancelamento e ofereça remarcar, sem insistir.`,
  },
}];

// Prepara o aviso para a Lorena assumir a conversa.
const d = $input.first().json;
const agora = DateTime.now().setZone(d.cfg.fuso);
const motivo = d.motivo || 'A paciente pediu para falar com a Lorena.';
const urgente = /urgente/i.test(motivo);

return [{
  json: {
    telefone: d.telefone,
    motivo,
    agora: agora.toFormat('yyyy-MM-dd HH:mm'),
    aviso_lorena:
      `${urgente ? 'URGENTE · ' : ''}Atendimento humano solicitado\n` +
      `Motivo: ${motivo}\n` +
      `Nome no WhatsApp: ${d.nome || 'não informado'}\n` +
      `Conversa: https://wa.me/${d.telefone}\n` +
      `O assistente parou de responder esta pessoa. Para ele voltar: #retomar ${d.telefone}`,
  },
}];

// Resposta final do pedido de atendimento humano para o agente.
return [{
  json: {
    resultado:
      'A Lorena foi avisada e o assistente vai pausar nesta conversa. ' +
      'Diga à paciente, em uma frase, que a Lorena vai responder pessoalmente por aqui assim que possível. Não faça novas perguntas.',
  },
}];
